CREATE TABLE centres (
	id SERIAL NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	address VARCHAR(300) NOT NULL, 
	city VARCHAR(80) NOT NULL, 
	latitude NUMERIC(9, 6), 
	longitude NUMERIC(9, 6), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_centre_name_city UNIQUE (name, city)
);

CREATE INDEX ix_centres_city ON centres (city);

CREATE TABLE diagnostic_tests (
	id SERIAL NOT NULL, 
	code VARCHAR(32) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	description TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	UNIQUE (name)
);


CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR(320) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(128) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT userrole CHECK (role IN ('USER', 'ADMIN'))
);

CREATE UNIQUE INDEX ix_users_email ON users (email);

CREATE TABLE webhook_events (
	id SERIAL NOT NULL, 
	event_id VARCHAR(128) NOT NULL, 
	event_type VARCHAR(64) NOT NULL, 
	payment_ref VARCHAR(64) NOT NULL, 
	payload JSONB NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	attempts INTEGER NOT NULL, 
	last_error VARCHAR(500), 
	received_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	last_attempt_at TIMESTAMP WITH TIME ZONE, 
	processed_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (event_id), 
	CONSTRAINT webhookeventstatus CHECK (status IN ('RECEIVED', 'PROCESSED', 'IGNORED', 'FAILED'))
);

CREATE INDEX ix_webhook_events_payment_ref ON webhook_events (payment_ref);
CREATE INDEX ix_webhook_events_status ON webhook_events (status, last_attempt_at);

CREATE TABLE centre_tests (
	id SERIAL NOT NULL, 
	centre_id INTEGER NOT NULL, 
	test_id INTEGER NOT NULL, 
	price NUMERIC(10, 2) NOT NULL, 
	is_active BOOLEAN DEFAULT true NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_centre_test UNIQUE (centre_id, test_id), 
	CONSTRAINT ck_centre_test_price_positive CHECK (price > 0), 
	FOREIGN KEY(centre_id) REFERENCES centres (id) ON DELETE CASCADE, 
	FOREIGN KEY(test_id) REFERENCES diagnostic_tests (id) ON DELETE RESTRICT
);

CREATE INDEX ix_centre_tests_test_id ON centre_tests (test_id);

CREATE TABLE bookings (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	centre_id INTEGER NOT NULL, 
	test_id INTEGER NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	appointment_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT fk_booking_centre_test FOREIGN KEY(centre_id, test_id) REFERENCES centre_tests (centre_id, test_id), 
	CONSTRAINT ck_booking_amount_positive CHECK (amount > 0), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT bookingstatus CHECK (status IN ('PENDING', 'CONFIRMED', 'FAILED', 'CANCELLED'))
);

CREATE INDEX ix_bookings_status_created ON bookings (status, created_at);
CREATE INDEX ix_bookings_user_created ON bookings (user_id, created_at);
CREATE UNIQUE INDEX uq_booking_active_slot ON bookings (user_id, centre_id, test_id, appointment_at) WHERE status IN ('PENDING', 'CONFIRMED');

CREATE TABLE payments (
	id SERIAL NOT NULL, 
	booking_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	provider_ref VARCHAR(64) NOT NULL, 
	idempotency_key VARCHAR(128), 
	failure_reason VARCHAR(255), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_payment_user_idem_key UNIQUE (user_id, idempotency_key), 
	CONSTRAINT ck_payment_amount_positive CHECK (amount > 0), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id) ON DELETE RESTRICT, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT paymentstatus CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED')), 
	UNIQUE (provider_ref)
);

CREATE INDEX ix_payments_user_created ON payments (user_id, created_at);
CREATE UNIQUE INDEX uq_payment_open_per_booking ON payments (booking_id) WHERE status IN ('PENDING', 'SUCCESS');

